"""Binary-control-only switch simulation of every MOS in the extracted barrier."""
from pathlib import Path
import json,re,hashlib,subprocess
ROOT=Path(__file__).resolve().parents[1];BASE=ROOT/'artifacts/analog_asic'
def sha(p):return hashlib.sha256(p.read_bytes()).hexdigest()
def main():
 cell='gf180_global_bin_barrier26_v2';d=BASE/'layout'/cell;out=BASE/'verification/extracted_switch_control'/cell;assert not out.exists();out.mkdir(parents=True);q=json.loads((d/'qualification.json').read_text());fq=json.loads((d/'flat_cap_qualification.json').read_text());assert q['magic_drc_count']==0 and q['gds_roundtrip_lvs_unique'] and fq['flat_lvs_unique'] and not fq['negative_aggregate_branches'];flat=d/(fq['flat_subcircuit']+'.spice');text=flat.read_text().replace('\n+',' ');ports=re.search(r'(?m)^\.subckt\s+\S+\s+([^\n]+)',text)[1].split();assert ports==q['ports'];devices=[line.split() for line in text.splitlines() if line.startswith('X')];assert len(devices)==2300;nodes=set(ports)
 for t in devices:
  assert t[5] in ['nfet_03v3','pfet_03v3'];assert t[4]==('VSS' if t[5]=='nfet_03v3' else 'VDD');nodes.update(t[1:5])
 names={n:'n'+str(i) for i,n in enumerate(sorted(nodes))};lines=['`timescale 1ns/1ps','module extracted_control('+','.join(names[p] for p in ports)+');','inout wire '+','.join(names[p] for p in ports)+';','wire '+','.join(names[n] for n in sorted(nodes-set(ports)))+';']
 for i,t in enumerate(devices):lines.append(('tranif1' if t[5]=='nfet_03v3' else 'tranif0')+' #(1,1) sw'+str(i)+'('+','.join(names[n] for n in [t[1],t[3],t[2]])+');')
 lines.append('endmodule');v=out/'extracted_control.v';v.write_text('\n'.join(lines)+'\n');connections={p:('actor_done['+p[10:]+']' if p.startswith('ACTOR_DONE') else {'CLK':'clk','CLEAR':'clear','QUEUE_DRAINED':'drained','COMPLETE':'complete','VDD':'vdd','VSS':'vss'}[p]) for p in ports}
 tb=['`timescale 1ns/1ps','module tb;','reg clk=0; reg clear; reg [24:0] actor_done; reg drained; wire complete; supply1 vdd; supply0 vss; integer errors=0; integer i;','always #500 clk=~clk;','extracted_control dut('+','.join('.'+names[p]+'('+connections[p]+')' for p in ports)+');', 'task check; input expected; input [255:0] tag; begin $display("CHECK %s %0d %0d",tag,complete,expected); if(complete !== expected) errors=errors+1; end endtask', 'initial begin clear=1; actor_done=0; drained=0; #2000 clear=0; for(i=0;i<25;i=i+1) begin #200 actor_done[i]=1; end #13000 check(0,"all_actors_queue_pending"); #5000 drained=1; #7000 check(1,"queue_drained_complete"); #2000 actor_done=0; drained=0; #1000 clear=1; #3000 check(0,"clear_removes_old_epoch"); #1000 clear=0; for(i=0;i<25;i=i+1) begin #200 actor_done[i]=1; end #4000 check(0,"second_bin_queue_pending"); #1000 drained=1; #9000 check(1,"second_bin_complete"); #7000 check(1,"complete_retained"); if(errors==0) $display("EXTRACTED_SWITCH_BARRIER_PASS"); else $fatal(1,"errors=%0d",errors); $finish; end','endmodule'];tp=out/'tb.v';tp.write_text('\n'.join(tb)+'\n');mapping=out/'node_map.json';mapping.write_text(json.dumps({'native_mos_count':2300,'node_names':names,'ports':connections,'abstract_switch_delay_ns':1,'device_count_preserved':True,'body_rail_connections_checked':True},indent=2)+'\n');image='eventspikeseg:torch2.2.2-cpu-verification-guarded';base=['docker','run','--rm','--network','none','--memory','2g','--cpus','2','--volume',f'{ROOT}:/workspace','--workdir','/workspace'];exe=out/'barrier.vvp';c=subprocess.run(base+['--entrypoint','iverilog',image,'-g2012','-s','tb','-o','/workspace/'+exe.relative_to(ROOT).as_posix(),'/workspace/'+v.relative_to(ROOT).as_posix(),'/workspace/'+tp.relative_to(ROOT).as_posix()],capture_output=True,text=True,timeout=120);cl=out/'compile.log';cl.write_text(c.stdout+c.stderr);assert c.returncode==0,c.stdout+c.stderr;r=subprocess.run(base+['--entrypoint','vvp',image,'/workspace/'+exe.relative_to(ROOT).as_posix()],capture_output=True,text=True,timeout=120);lp=out/'simulation.log';lp.write_text(r.stdout+r.stderr);print(r.stdout+r.stderr);passed=r.returncode==0 and 'EXTRACTED_SWITCH_BARRIER_PASS' in r.stdout;files={Path(__file__),d/'qualification.json',d/'flat_cap_qualification.json',flat,v,tp,mapping,cl,lp,exe};rp=BASE/'results/gf180_global_bin_barrier26_v2_extracted_switch_control.json';assert not rp.exists();report={'module_simulation_completed':r.returncode==0,'all_extracted_binary_barrier_checks_pass':passed,'simulation_level':'extracted_native_CMOS_switch_logic_only','native_mos_count':2300,'scope':'Every2300 native MOS in the actual flat extracted folded26-leaf control barrier becomes a bidirectional gate-controlled switch, preserving D/G/S connections and verified body rails. Binary control only:25 actor-done tokens plus queue-drained, clear and two successive bins.1ns abstract switch delay is arbitrary and NOT calibrated transistor, RC or analog timing. Capacitors, channel strength/threshold/leakage/noise and metastability are not modeled. Native SPICE120s timeout at1.714us remains preserved; this completes functional control simulation, not full analog transient or5ms timing qualification. Analog SNN membranes/weights/adaptation remain native analog, with no numerical digital fallback.','cases':[{'case':'all_actors_then_queue_drain'},{'case':'clear_old_epoch'},{'case':'second_bin_and_hold'}],'native_SPICE_transient_completed':False,'full_5ms_population_service_accepted':False,'full_chip_layout_complete':False,'sha256':{p.relative_to(ROOT).as_posix():sha(p) for p in sorted(files)}};rp.write_text(json.dumps(report,indent=2)+'\n');assert passed
if __name__=='__main__':main()
